// === Tab: mySketch ===
let pg;
let theShader1;
let canvas;

function setup() {
  canvas = createCanvas(500, 500,WEBGL);
  pg = createGraphics(width, height);
  pg.noStroke();
  pg.fill('#776B5D');
  background('#000000');
  noStroke();

}

function draw() {
  translate(-width / 2,-height / 2);  
  grid(Math.round(random(2,6)));
  noLoop();
}

/** num個で分割したグリッドを画面いっぱいに生成する
* @method grid
* @param  {Number}        num           画面の分割数
*/
const grid = (num) => {
    const n1 = num + 1;
    const margin_left = width / n1 / n1;
    const margin_bottom = height / n1 / n1;

    const nw = width / n1;
    const nh = height / n1;

    for (let i = 0; i < num; i++) {
      for (let j = 0; j < num; j++) {
        const x = nw * i + margin_left * (i + 1);
        const y = nh * j + margin_bottom * (j + 1);
        shaderRandom(Math.round(random(0,3)));
        circle(x + nw / 2, y + nw / 2, nw);
      }
    }
};


/** 受け取ったランダムな値からどのシェーダーを渡すか決める関数
* @method shaderRandom
* @param  {Number}        rand           ランダムな値(int)
*/
const shaderRandom = (rand) =>{
  if(rand === 0){
    theShader1 = createShader(vert, shader_grid.fs);
    shader(theShader1);
    theShader1.setUniform(`u_tex`, pg);
    theShader1.setUniform(`u_time`, frameCount / 35);
    theShader1.setUniform('u_resolution', [pg.width, pg.height]);
  }else if(rand === 1){
    theShader1 = createShader(vert, shader_mosaic.fs);
    shader(theShader1);
    theShader1.setUniform(`u_tex`, pg);
    theShader1.setUniform(`u_time`, frameCount / 35);
    theShader1.setUniform('u_resolution', [pg.width, pg.height]);
  }else if(rand === 2){
    theShader1 = createShader(vert, shader_diamond.fs);
    shader(theShader1);
    theShader1.setUniform(`u_tex`, pg);
    theShader1.setUniform(`u_time`, frameCount / 35);
    theShader1.setUniform('u_resolution', [pg.width, pg.height]);
  }else{
    theShader1 = createShader(vert, shader_highline.fs);
    shader(theShader1);
    theShader1.setUniform(`u_tex`, pg);
    theShader1.setUniform(`u_time`, frameCount / 35);
    theShader1.setUniform('u_resolution', [pg.width, pg.height]);
  }
}

keyPressed = () => {
  if (key === 's') {
    saveCanvas(canvas, 'canvas', 'png');
    //saveGif('canvas', 4);
  }
};

const vert = `
  precision highp float;
  precision highp int;

  attribute vec3 aPosition;
  attribute vec2 aTexCoord;

  varying vec2 vTexCoord;

  uniform mat4 uProjectionMatrix;
  uniform mat4 uModelViewMatrix;

  void main() {
    vec4 positionVec4 = vec4(aPosition, 1.0);
    gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
    vTexCoord = aTexCoord;
  }
`;

const shader_grid = {
  fs: `
  precision highp float;
  precision highp int;

  varying vec2 vTexCoord;

  uniform sampler2D u_tex;
  uniform float u_time;
  uniform vec2 u_resolution;

  float PI = 3.14159265358979;

  vec2 tile(vec2 _st, float _zoom){
    _st *= _zoom;
    return fract(_st);
  }

  float box(vec2 _st, vec2 _size, float _smoothEdges){
    _size = vec2(0.5)-_size*0.5;
    vec2 aa = vec2(_smoothEdges*0.5);
    vec2 uv = smoothstep(_size,_size+aa,_st);
    uv *= smoothstep(_size,_size+aa,vec2(1.0)-_st);
    return uv.x*uv.y;
  }

  void main(){
    vec2 uv = vTexCoord;
    vec4 tex = texture2D(u_tex, uv);

    gl_FragColor = tex;

    vec2 st = vTexCoord;
    //gl_FragCoord.xy/u_resolution.xy;
    vec3 color = vec3(0.0);

    st = tile(st,4.);

    color = vec3(box(st,vec2(0.7),0.01));
    gl_FragColor = vec4(color,1.0);
  }
`}

// 参考：https://thebookofshaders.com/09/?lan=jp
const shader_diamond = {
  fs:`
  precision highp float;
  precision highp int;

  varying vec2 vTexCoord;

  uniform float u_time;
  uniform vec2 u_resolution;

  float PI = 3.14159265358979;

vec2 rotate2D(vec2 _st, float _angle){
    _st -= 0.5;
    _st =  mat2(cos(_angle),-sin(_angle),
                sin(_angle),cos(_angle)) * _st;
    _st += 0.5;
    return _st;
}

vec2 tile(vec2 _st, float _zoom){
    _st *= _zoom;
    return fract(_st);
}

float box(vec2 _st, vec2 _size, float _smoothEdges){
    _size = vec2(0.5)-_size*0.5;
    vec2 aa = vec2(_smoothEdges*0.5);
    vec2 uv = smoothstep(_size,_size+aa,_st);
    uv *= smoothstep(_size,_size+aa,vec2(1.0)-_st);
    return uv.x*uv.y;
}

void main(){
    vec2 st = vTexCoord;
    vec3 color = vec3(0.0);

    st = tile(st,4.);

    st = rotate2D(st,PI*0.25);

    color = vec3(box(st,vec2(0.7),0.01));
    gl_FragColor = vec4(color,1.0);
}
`
}

// 参考：https://thebookofshaders.com/edit.php#10/2d-random-mosaic.frag
const shader_mosaic = {
  fs: `
  precision highp float;
  precision highp int;

  varying vec2 vTexCoord;

  uniform float u_time;
  uniform vec2 u_resolution;

  float PI = 3.14159265358979;
float random (vec2 st) {
    return fract(sin(dot(st.xy,
                         vec2(12.9898,78.233)))*
        43758.5453123);
}

  void main() {
    vec2 st = vTexCoord;

    st *= 10.0; // Scale the coordinate system by 10
    vec2 ipos = floor(st);  // get the integer coords
    vec2 fpos = fract(st);  // get the fractional coords

    // Assign a random value based on the integer coord
    vec3 color = vec3(random( ipos ));

    // Uncomment to see the subdivided grid
    // color = vec3(fpos,0.0);

    gl_FragColor = vec4(color,1.0);
}
`}

// 参考：https://renard.hateblo.jp/entry/2023/07/05/122300
const shader_highline = {
  fs:`
precision highp float;
precision highp int;

varying vec2 vTexCoord;

uniform sampler2D u_tex;
uniform float u_time;
uniform vec2 u_resolution;

float pi = 3.14159265358979;
float X = .211324865405187;
float Y = .36602540378443;
float Z = -.577350269189626;
float W = .024390243902439;

vec3 permute(vec3 x) { return mod( x*x*34.+x, 289.); }

float snoise(vec2 v) {
	vec2 i = floor(v + (v.x+v.y)*Y),
    x0 = v -   i + (i.x+i.y)*X,
    j = step(x0.yx, x0),
    x1 = x0+X-j,
    x3 = x0+Z;
  i = mod(i,289.);

  vec3 p = permute( permute( i.y + vec3(0, j.y, 1 )) + i.x + vec3(0, j.x, 1 ) ),
    m = max( .5 - vec3(dot(x0,x0), dot(x1,x1), dot(x3,x3)), 0.),
    x = 2. * fract(p * W) - 1.,
    h = abs(x) - .5,
    a0 = x - floor(x + .5),
    g = a0 * vec3(x0.x,x1.x,x3.x) + h * vec3(x0.y,x1.y,x3.y);
	m = m*m*m*m* ( 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h ) );

	return .5 + 65. * dot(m, g);
}

void main() {
  vec2 uv = vTexCoord;

  vec2 p= vTexCoord;
  p.y += 0.09 * sin(p.x*pi*5.0 + u_time);

  vec3 col = 0.5 + 0.5*cos(u_time+uv.xyx+vec3(0,2,4));
  float l=.2;
  float f=5.;
  float n=snoise(p*5.)*.5+.5;
  float c=float(fract(n*f)<l);

  vec3 col_highline  = vec3(0,0,0);
  col_highline += vec3(c,c,c);

  gl_FragColor =  vec4(col_highline,1.0);
}
`
}

